Transferencia internacional de datos.ejemplo:
# Política OPA: impedir despliegue de buckets fuera del EEE en un plan de Terraform
package privacy.transfer
eu_locations := {"EU", "EUROPE-WEST1", "EUROPE-WEST3"}
deny[msg] {
  r := input.resource_changes[_]
  r.type == "google_storage_bucket"
  loc := upper(r.change.after.location)
  not eu_locations[loc]
  msg := sprintf("Región fuera del EEE: %s (%s)", [r.address, loc])
}
